import pytest

from vizcode import structure

# one generated file per language, by its generator's header marker: a data type with fields, a method and a call
MARKED = {
    "go": ("svc/api/types.gen.go",
           "// Code generated by apigen v1.2. DO NOT EDIT.\npackage api\n\ntype Order struct {\n\tID string\n}\n\n"
           "func (o *Order) Valid() bool { return check(o.ID) }\n"),
    "python": ("svc/models.py",
               "# Generated by the protocol buffer compiler.  DO NOT EDIT!\nfrom dataclasses import dataclass\n\n\n"
               "@dataclass\nclass Order:\n    id: str\n\n    def valid(self) -> bool:\n        return check(self.id)\n"),
    "csharp": ("svc/Order.cs",
               "// <auto-generated>\n//   Generated from order.proto\n// </auto-generated>\nnamespace Shop;\n\n"
               "public class Order\n{\n    public string Id { get; set; }\n"
               "    public bool Valid() { return Check(Id); }\n}\n"),
    "typescript": ("svc/order.ts",
                   "// @generated by schema-gen\nexport class Order {\n  id: string;\n"
                   "  valid(): boolean { return check(this.id); }\n}\n"),
    "java": ("svc/Order.java",
             "package shop;\n\n@javax.annotation.Generated(value = \"by a compiler\")\npublic class Order {\n"
             "  public String id;\n  private int memoizedSize;\n  public boolean valid() { return check(id); }\n}\n"),
}


@pytest.mark.parametrize("lang", MARKED)
def test_a_generated_file_keeps_its_data_types_only(make_repo, lang):
    path, src = MARKED[lang]
    s = structure.build(make_repo({path: src, "svc/main" + path[path.rindex("."):]: ""}))
    assert s["generated"] == [path]
    mine = [n for n in s["nodes"] if n["file"] == path and n["kind"] in ("class", "method")]
    assert [(n["kind"], n["name"], [f["name"] for f in n["fields"]]) for n in mine] == [
        ("class", "Order", [mine[0]["fields"][0]["name"]])]
    assert mine[0]["metrics"]["methods"] == 0
    assert s["facts"][path]["calls"] == []
    assert "Generated files, scanned for their data types and routes only (1): " + path in structure.summary_md(s)


ROUTER = """// Code generated by apigen v1.2. DO NOT EDIT.
package api

import (
	"net/http"

	"github.com/go-chi/chi/v5"
)

type ServerInterface interface {
	ListOrders(w http.ResponseWriter, r *http.Request)
}

type wrapper struct {
	Handler ServerInterface
}

func (w *wrapper) ListOrders(rw http.ResponseWriter, r *http.Request) { w.Handler.ListOrders(rw, r) }

func Handler(si ServerInterface, r chi.Router) http.Handler {
	w := wrapper{Handler: si}
	r.Get("/orders", w.ListOrders)
	return r
}
"""


def test_a_generated_router_keeps_its_routes_and_their_handlers(make_repo):
    s = structure.build(make_repo({"svc/api/router.gen.go": ROUTER, "svc/main.go": "package main\n"}))
    routes = s["facts"]["svc/api/router.gen.go"]["routes"]
    assert [(r["method"], r["path"]) for r in routes] == [("GET", "/orders")]
    kept = {n["id"] for n in s["nodes"] if n["file"] == "svc/api/router.gen.go"}
    assert routes[0]["handler"] in kept
    # a private type is no data type even with fields; a method no route names goes
    assert not any(n["name"] in ("wrapper", "ListOrders") for n in s["nodes"])


def test_markers_count_only_in_the_header(make_repo):
    late = "package svc\n\n" + "// filler\n" * 45 + "// Code generated rows: DO NOT EDIT them by hand.\nfunc F() {}\n"
    repo = make_repo({"svc/late.go": late,
                      "svc/reports.go": "// Generated reports go to the archive.\npackage svc\n\nfunc G() {}\n"})
    s = structure.build(repo)
    assert s["generated"] == []
    assert {n["name"] for n in s["nodes"] if n["kind"] == "method"} == {"F", "G"}


def test_a_grpc_java_class_marked_beside_it_is_generated(make_repo):
    # `@generated=omit` drops the header: the class annotation is the only mark, past the header lines
    stub = ("package shop;\n\n" + "import a.B;\n" * 45 + "@io.grpc.stub.annotations.GrpcGenerated\n"
            "public final class CartServiceGrpc {\n  public static void bindService() {}\n}\n")
    s = structure.build(make_repo({"pom.xml": "<project/>", "src/main/java/shop/CartServiceGrpc.java": stub,
                                   "src/main/java/shop/Notes.java": "package shop;\n// see GrpcGenerated\nclass Notes {}\n"}))
    assert s["generated"] == ["src/main/java/shop/CartServiceGrpc.java"]


def test_protoc_python_stubs_add_no_classes(make_repo):
    stubs = ("# Generated by the gRPC Python protocol compiler plugin. DO NOT EDIT!\nimport grpc\n\n\n"
             "class OrdersStub(object):\n    def __init__(self, channel):\n"
             "        self.Place = channel.unary_unary('/shop.Orders/Place')\n\n\n"
             "class OrdersServicer(object):\n    def Place(self, request, context):\n        raise NotImplementedError()\n\n\n"
             "def add_OrdersServicer_to_server(servicer, server):\n    server.add_generic_rpc_handlers(())\n")
    repo = make_repo({"svc/__init__.py": "", "svc/shop_pb2_grpc.py": stubs, "svc/shop_pb2.py": "DESCRIPTOR = None\n",
                      "svc/server.py": "from . import shop_pb2_grpc\n\n\nclass Orders(shop_pb2_grpc.OrdersServicer):\n"
                                       "    def Place(self, request, context):\n        return None\n"})
    s = structure.build(repo)
    assert s["generated"] == ["svc/shop_pb2.py", "svc/shop_pb2_grpc.py"]
    assert [n["id"] for n in s["nodes"] if n["kind"] in ("class", "method")] == [
        "svc::svc.server.Orders", "svc::svc.server.Orders#Place/2"]
    assert [g["side"] for g in s["facts"]["svc/server.py"]["grpc"]] == ["server"]


def test_vendored_bundles_and_folders_are_excluded(make_repo):
    minified = "/*! lib v1 */\n!function(t){" + "var a=t.x;" * 300 + "}(this);\n"
    repo = make_repo({"web/views/lib.js": minified, "web/views/app.js": "function show() {}\n",
                      "web/third_party/chart.js": "function draw() {}\n", "svc/__init__.py": "",
                      "svc/vendor/six.py": "def x():\n    pass\n", "third_party/proto_util.py": "def y():\n    pass\n",
                      "svc/main.py": "def z():\n    pass\n"})
    s = structure.build(repo)
    assert sorted(s["files"]) == ["svc/__init__.py", "svc/main.py", "web/views/app.js"]
    assert {"web/views/lib.js", "web/third_party/chart.js", "svc/vendor/six.py", "third_party/proto_util.py"} <= set(
        s["excluded"])


def test_a_generated_type_keeps_the_fields_its_language_names_public(make_repo):
    s = structure.build(make_repo({
        "svc/models_pb2.py": "class Order:\n    id: str\n    _cache: int\n",
        "svc/order.pb.go": "package svc\n\ntype Order struct {\n\tsizeCache int32\n\tID string\n}\n\n"
                           "type state struct {\n\tx int\n}\n\ntype Hidden struct {\n\tx int\n}\n",
        "svc/main.py": "", "svc/main.go": "package svc\n"}))
    fields = {(n["file"], n["name"]): [f["name"] for f in n.get("fields", [])] for n in s["nodes"] if n["kind"] == "class"}
    assert fields == {("svc/models_pb2.py", "Order"): ["id"], ("svc/order.pb.go", "Order"): ["ID"]}


def test_a_generated_type_keeps_the_fields_its_modifiers_make_public(make_repo):
    marker = "// Code generated by modelgen. DO NOT EDIT.\n"
    s = structure.build(make_repo({
        "svc/Order.java": marker + "package shop;\n\npublic class Order {\n  private String id_;\n  public String note;\n"
                          "  protected int size;\n  long cents;\n}\n\npublic class Hidden {\n  private int x;\n}\n",
        "svc/Order.cs": marker + "namespace Shop;\n\npublic class Line\n{\n    public string Sku { get; set; }\n"
                        "    private int Seen { get; set; }\n    int Count { get; set; }\n}\n",
        "svc/Order.kt": marker + "package shop\n\nclass Bay(val id: String, private val cache: Int) {\n"
                        "  internal var level: Int = 0\n  private var seen: Int = 0\n}\n",
        "svc/Order.php": marker + "<?php\nnamespace Shop;\n\nclass Charge {\n  public string $id;\n  private int $seen;\n"
                         "  public function __construct(protected int $n, public int $total) {}\n}\n",
        "svc/Main.java": "package shop;\n\nclass Main {\n  private String id;\n}\n",
        "svc/order.proto": "syntax = \"proto3\";\npackage shop;\n\nmessage Hidden {\n  int32 x = 1;\n}\n"}))
    fields = {(n["file"], n["name"]): [(f["name"], f.get("visibility")) for f in n.get("fields", [])]
              for n in s["nodes"] if n["kind"] == "class"}
    assert fields == {("svc/Order.java", "Order"): [("note", "public"), ("cents", "public")],
                      ("svc/Order.cs", "Line"): [("Sku", "public")],
                      ("svc/Order.kt", "Bay"): [("id", "public"), ("level", "public")],
                      ("svc/Order.php", "Charge"): [("id", "public"), ("total", "public")],
                      # a class that is not generated keeps every field
                      ("svc/Main.java", "Main"): [("id", "private")],
                      # a generated class with no public field is no data type: the .proto's message stands in
                      ("svc/order.proto", "Hidden"): [("x", None)]}


def test_a_file_with_old_mac_line_endings_is_no_bundle(make_repo):
    src = "\r".join(f"function step{i}() {{ return fetch('/api/step/{i}'); }}" for i in range(40)) + "\r"
    s = structure.build(make_repo({"web/static/js/login.js": src}))
    assert "web/static/js/login.js" in s["files"]
    assert {n["name"]: n["line"] for n in s["nodes"] if n["kind"] == "method"}["step39"] == 40
